import{_ as t,o,c as a,a3 as n}from"./chunks/framework.BTQ4eCVb.js";const u=JSON.parse('{"title":"Attendance — Production Guide","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Attendance — Production Guide | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/deployment/attendance"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Attendance — Production Guide | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/deployment/attendance"}]]},"headers":[],"relativePath":"deployment/attendance.md","filePath":"deployment/attendance.md","lastUpdated":1788108809000}'),i={name:"deployment/attendance.md"};function r(l,e,c,d,s,m){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="attendance-—-production-guide" tabindex="-1">Attendance — Production Guide <a class="header-anchor" href="#attendance-—-production-guide" aria-label="Permalink to &quot;Attendance — Production Guide&quot;">​</a></h1><h2 id="licensing" tabindex="-1">Licensing <a class="header-anchor" href="#licensing" aria-label="Permalink to &quot;Licensing&quot;">​</a></h2><ul><li>Catalog slug: <code>attendance</code></li><li>Category: <code>hr</code>, <code>sort_order = 30</code></li><li>Free Marketplace opt-in</li><li><strong>Hard dependency</strong> on <code>employees</code> (<code>add_attendance_employees_dependency</code>)</li><li>Current catalog version: <strong>1.2.0</strong> (self check-in/out, reasons, remote grace)</li></ul><h2 id="bootstrap" tabindex="-1">Bootstrap <a class="header-anchor" href="#bootstrap" aria-label="Permalink to &quot;Bootstrap&quot;">​</a></h2><ol><li>Ensure Employees schema + catalog exist</li><li>Migrate <code>attendance_records</code> + <code>attendance_reasons</code> (+ check-in reason / work_mode columns)</li><li>Register module + permissions + dependency row</li><li>Deploy Attendance UI under HR</li></ol><h2 id="timezone" tabindex="-1">Timezone <a class="header-anchor" href="#timezone" aria-label="Permalink to &quot;Timezone&quot;">​</a></h2><p>Self check-in “today”, the HH:MM timer, and late classification use <strong>Settings → General → Timezone</strong> (same convention as Daily Reminder Time, meetings, and task/follow-up dues). Office start/end and remote start are workspace-local <code>H:i</code> values — not server UTC. See <a href="/developer-guide/tenant-settings#timezone-and-scheduled-datetimes">Workspace timezone convention</a>.</p><h2 id="deploy-checklist-1-2-0" tabindex="-1">Deploy checklist (1.2.0) <a class="header-anchor" href="#deploy-checklist-1-2-0" aria-label="Permalink to &quot;Deploy checklist (1.2.0)&quot;">​</a></h2><ol><li>Run migrations through <code>2026_08_28_203200</code> (reasons table, record columns, catalog bump) and <code>2026_08_29_003000</code> (<code>attendance.force.delete</code> grant for admin defaults)</li><li>Confirm Marketplace blocks install when Employees is missing</li><li>Confirm default roles: staff has <code>attendance.create</code> + <code>attendance.update</code>; admin has <code>attendance.force.delete</code></li><li>Smoke: <ul><li>Enable Employees + Attendance</li><li>Linked user: <strong>Check in</strong> (on-site/remote) → timer survives reload → <strong>Check out</strong></li><li>Late path: <strong>Other</strong> requires free text</li><li>Settings: self-check toggle, auto-login (default off), remote grace</li></ul></li><li>When <strong>Auto check-in on login</strong> is on and <strong>Require late check-in reason</strong> is on, late logins <strong>do not</strong> auto check-in (staff must use explicit Check in with a reason)</li><li>Pest: <code>tests/Feature/Tenant/Attendance</code></li><li>Playwright: <code>npm run test:e2e:attendance</code> (modules suite; authz may skip on pre-entitled demo)</li><li><a href="/deployment/hr-phase7-production-readiness">Production Readiness</a> · <a href="/deployment/hr-phase7-security-audit">Security Audit</a></li></ol><h2 id="related-payroll-1-2-0" tabindex="-1">Related Payroll 1.2.0 <a class="header-anchor" href="#related-payroll-1-2-0" aria-label="Permalink to &quot;Related Payroll 1.2.0&quot;">​</a></h2><p>If shipping My salary slips in the same release: migrate <code>2026_08_28_204000</code> (<code>payroll.view_own</code> + payroll catalog <strong>1.2.0</strong>) and smoke <strong>My salary slips</strong> PDF download for a linked staff user.</p>',11)])])}const h=t(i,[["render",r]]);export{u as __pageData,h as default};
